fn process(text: str) -> i64 {
    if str_len(text) == 0 {
        println("no header")
        return 2
    }
    let lines = str_split(text, "\n")
    let nl = len(lines)
    let nlines = nl
    if str_eq(lines[nl - 1], "") {
        nlines = nl - 1
    }
    let names = str_split(lines[0], ",")
    let a = len(names)
    let sums = arr_repeat(0, a)
    for i in 1..nlines {
        let fields = str_split(lines[i], ",")
        if len(fields) != a {
            println("line " + to_str(i + 1) + ": expected " + to_str(a) + " fields, got " + to_str(len(fields)))
            return 3
        }
        for j in 0..a {
            match parse_int(fields[j]) {
                Ok(v) => {
                    sums[j] = sums[j] + v
                }
                Err(_) => {
                    println("line " + to_str(i + 1) + ": bad number \"" + fields[j] + "\"")
                    return 4
                }
            }
        }
    }
    let out = ""
    for j in 0..a {
        out = out + names[j] + "=" + to_str(sums[j]) + "\n"
    }
    match dir_create("./out") {
        Err(e) => {
            eprintln("cannot create dir: {e}")
            1
        }
        Ok(_) => {
            match write_file("./out/sums.txt", out) {
                Ok(_) => {
                    println("rows: " + to_str(nlines - 1))
                    0
                }
                Err(e) => {
                    eprintln("cannot write: {e}")
                    1
                }
            }
        }
    }
}

fn main() -> i64 {
    match read_file("./data/table.csv") {
        Err(_) => {
            println("missing input")
            5
        }
        Ok(text) => process(text)
    }
}
